import type {ShaderModule} from '@luma.gl/shadertools';

const uniformBlock = `\
uniform arcTripsUniforms {
  bool fadeTrail;
  float trailLength;
  float currentTime;
  bool showFullArc;
  float dotSize;
  float dotTrailLength;
  float animationSpeed;
} arcTrips;
`;

export type ArcTripsProps = {
  fadeTrail: boolean;
  trailLength: number;
  currentTime: number;
  showFullArc: boolean;
  dotSize: number;
  dotTrailLength: number;
  animationSpeed: number;
};

export const arcTripsUniforms = {
  name: 'arcTrips',
  vs: uniformBlock,
  fs: uniformBlock,
  uniformTypes: {
    fadeTrail: 'f32',
    trailLength: 'f32',
    currentTime: 'f32',
    showFullArc: 'f32',
    dotSize: 'f32',
    dotTrailLength: 'f32',
    animationSpeed: 'f32'
  }
} as const satisfies ShaderModule<ArcTripsProps>;

