import {
  Layer,
  project32,
  picking,
  UNIT,
  UpdateParameters,
  LayerProps,
  LayerDataSource,
  Unit,
  AccessorFunction,
  Position,
  Accessor,
  Color,
  DefaultProps
} from '@deck.gl/core';

import {Model} from '@luma.gl/engine';

import {arcUniforms, ArcProps} from '../arc-layer/arc-layer-uniforms';
import {arcTripsUniforms, ArcTripsProps} from './arc-trips-layer-uniforms';
import vs from './arc-trips-layer-vertex.glsl';
import fs from './arc-trips-layer-fragment.glsl';

const DEFAULT_COLOR: [number, number, number, number] = [0, 0, 0, 255];

const defaultProps: DefaultProps<ArcTripsLayerProps> = {
  getSourcePosition: {type: 'accessor', value: (x: any) => x.sourcePosition},
  getTargetPosition: {type: 'accessor', value: (x: any) => x.targetPosition},
  getSourceColor: {type: 'accessor', value: DEFAULT_COLOR},
  getTargetColor: {type: 'accessor', value: DEFAULT_COLOR},
  getWidth: {type: 'accessor', value: 1},
  getHeight: {type: 'accessor', value: 1},
  getTilt: {type: 'accessor', value: 0},

  greatCircle: false,
  numSegments: {type: 'number', value: 50, min: 1},

  widthUnits: 'pixels',
  widthScale: {type: 'number', value: 1, min: 0},
  widthMinPixels: {type: 'number', value: 0, min: 0},
  widthMaxPixels: {type: 'number', value: Number.MAX_SAFE_INTEGER, min: 0},

  // TripsLayer properties
  fadeTrail: true,
  trailLength: {type: 'number', value: 120, min: 0},
  currentTime: {type: 'number', value: 0, min: 0},
  showFullArc: true,
  dotSize: {type: 'number', value: 0.1, min: 0.01, max: 1.0},
  dotTrailLength: {type: 'number', value: 0.3, min: 0.0, max: 1.0},
  animationSpeed: {type: 'number', value: 1.0, min: 0.1, max: 10.0},
  getSourceTimestamp: {type: 'accessor', value: (d: any) => d.sourceTimestamp || 0},
  getTargetTimestamp: {type: 'accessor', value: (d: any) => d.targetTimestamp || 1}
};

/** All properties supported by ArcTripsLayer. */
export type ArcTripsLayerProps<DataT = unknown> = _ArcTripsLayerProps<DataT> & LayerProps;

/** Properties added by ArcTripsLayer. */
type _ArcTripsLayerProps<DataT> = {
  data: LayerDataSource<DataT>;
  
  // ArcLayer properties
  /**
   * If `true`, create the arc along the shortest path on the earth surface.
   * @default false
   */
  greatCircle?: boolean;

  /**
   * The number of segments used to draw each arc.
   * @default 50
   */
  numSegments?: number;

  /**
   * The units of the line width, one of `'meters'`, `'common'`, and `'pixels'`
   * @default 'pixels'
   */
  widthUnits?: Unit;

  /**
   * The scaling multiplier for the width of each line.
   * @default 1
   */
  widthScale?: number;

  /**
   * The minimum line width in pixels.
   * @default 0
   */
  widthMinPixels?: number;

  /**
   * The maximum line width in pixels.
   * @default Number.MAX_SAFE_INTEGER
   */
  widthMaxPixels?: number;

  /**
   * Method called to retrieve the source position of each object.
   * @default object => object.sourcePosition
   */
  getSourcePosition?: AccessorFunction<DataT, Position>;

  /**
   * Method called to retrieve the target position of each object.
   * @default object => object.targetPosition
   */
  getTargetPosition?: AccessorFunction<DataT, Position>;

  /**
   * The rgba color is in the format of `[r, g, b, [a]]`.
   * @default [0, 0, 0, 255]
   */
  getSourceColor?: Accessor<DataT, Color>;

  /**
   * The rgba color is in the format of `[r, g, b, [a]]`.
   * @default [0, 0, 0, 255]
   */
  getTargetColor?: Accessor<DataT, Color>;

  /**
   * The line width of each object, in units specified by `widthUnits`.
   * @default 1
   */
  getWidth?: Accessor<DataT, number>;

  /**
   * Multiplier of layer height. `0` will make the layer flat.
   * @default 1
   */
  getHeight?: Accessor<DataT, number>;

  /**
   * Use to tilt the arc to the side if you have multiple arcs with the same source and target positions.
   * @default 0
   */
  getTilt?: Accessor<DataT, number>;

  // TripsLayer properties
  /**
   * Whether or not the path fades out.
   * @default true
   */
  fadeTrail?: boolean;
  
  /**
   * Trail length.
   * @default 120
   */
  trailLength?: number;
  
  /**
   * The current time of the frame.
   * @default 0
   */
  currentTime?: number;
  
  /**
   * Whether to show the full arc with animation effects or only the animated portion.
   * @default true
   */
  showFullArc?: boolean;
  
  /**
   * Size of the moving dot (0.0 to 1.0).
   * @default 0.1
   */
  dotSize?: number;
  
  /**
   * Length of the trail behind the dot (0.0 to 1.0).
   * @default 0.3
   */
  dotTrailLength?: number;
  
  /**
   * Method called to retrieve the source timestamp of each object.
   * @default object => object.sourceTimestamp || 0
   */
  getSourceTimestamp?: AccessorFunction<DataT, number>;
  
  /**
   * Method called to retrieve the target timestamp of each object.
   * @default object => object.targetTimestamp || 1
   */
  getTargetTimestamp?: AccessorFunction<DataT, number>;
  
  /**
   * Speed multiplier for the animation. Higher values make the dots move faster.
   * @default 1.0
   */
  animationSpeed?: number;
};

/** Render animated arcs with trail effects that represent vehicle trips. */
class ArcTripsLayer<DataT = any, ExtraPropsT extends {} = {}> extends Layer<
  ExtraPropsT & Required<_ArcTripsLayerProps<DataT>>
> {
  static layerName = 'ArcTripsLayer';
  static defaultProps = defaultProps;

  state!: {
    model?: Model;
  };

  getBounds(): [number[], number[]] | null {
    return this.getAttributeManager()?.getBounds([
      'instanceSourcePositions',
      'instanceTargetPositions'
    ]);
  }

  getShaders() {
    return super.getShaders({vs, fs, modules: [project32, picking, arcUniforms, arcTripsUniforms]});
  }

  // This layer has its own wrapLongitude logic
  get wrapLongitude() {
    return false;
  }

  initializeState() {
    const attributeManager = this.getAttributeManager()!;

    /* eslint-disable max-len */
    attributeManager.addInstanced({
      instanceSourcePositions: {
        size: 3,
        type: 'float64',
        fp64: this.use64bitPositions(),
        transition: true,
        accessor: 'getSourcePosition'
      },
      instanceTargetPositions: {
        size: 3,
        type: 'float64',
        fp64: this.use64bitPositions(),
        transition: true,
        accessor: 'getTargetPosition'
      },
      instanceSourceColors: {
        size: this.props.colorFormat.length,
        type: 'unorm8',
        transition: true,
        accessor: 'getSourceColor',
        defaultValue: DEFAULT_COLOR
      },
      instanceTargetColors: {
        size: this.props.colorFormat.length,
        type: 'unorm8',
        transition: true,
        accessor: 'getTargetColor',
        defaultValue: DEFAULT_COLOR
      },
      instanceWidths: {
        size: 1,
        transition: true,
        accessor: 'getWidth',
        defaultValue: 1
      },
      instanceHeights: {
        size: 1,
        transition: true,
        accessor: 'getHeight',
        defaultValue: 1
      },
      instanceTilts: {
        size: 1,
        transition: true,
        accessor: 'getTilt',
        defaultValue: 0
      },
      // Time-related attributes
      instanceSourceTimestamps: {
        size: 1,
        type: 'float32',
        transition: true,
        accessor: 'getSourceTimestamp',
        defaultValue: 0
      },
      instanceTargetTimestamps: {
        size: 1,
        type: 'float32',
        transition: true,
        accessor: 'getTargetTimestamp',
        defaultValue: 1
      }
    });
    /* eslint-enable max-len */
  }

  updateState(params: UpdateParameters<this>): void {
    super.updateState(params);

    if (params.changeFlags.extensionsChanged) {
      this.state.model?.destroy();
      this.state.model = this._getModel();
      this.getAttributeManager()!.invalidateAll();
    }
  }

  draw({uniforms}) {
    const {
      widthUnits,
      widthScale,
      widthMinPixels,
      widthMaxPixels,
      greatCircle,
      wrapLongitude,
      numSegments,
      fadeTrail,
      trailLength,
      currentTime,
      showFullArc,
      dotSize,
      dotTrailLength,
      animationSpeed
    } = this.props;
    
    const arcProps: ArcProps = {
      numSegments,
      widthUnits: UNIT[widthUnits],
      widthScale,
      widthMinPixels,
      widthMaxPixels,
      greatCircle,
      useShortestPath: wrapLongitude
    };

    const arcTripsProps: ArcTripsProps = {
      fadeTrail,
      trailLength,
      currentTime,
      showFullArc,
      dotSize,
      dotTrailLength,
      animationSpeed
    };

    const model = this.state.model!;
    model.shaderInputs.setProps({arc: arcProps, arcTrips: arcTripsProps});
    model.setVertexCount(numSegments * 2);
    model.draw(this.context.renderPass);
  }

  protected _getModel(): Model {
    return new Model(this.context.device, {
      ...this.getShaders(),
      id: this.props.id,
      bufferLayout: this.getAttributeManager()!.getBufferLayouts(),
      topology: 'triangle-strip',
      isInstanced: true
    });
  }
}

export default ArcTripsLayer;

